class Solution {
    public int rearrangeSticks(int n,int k){
        long[][] dp=new long[n+1][k+1];
        dp[0][0]=1;
        for(int length=1;length<=n;length++)for(int visible=1;visible<=Math.min(length,k);visible++)dp[length][visible]=(dp[length-1][visible-1]+(length-1)*dp[length-1][visible])%1_000_000_007;
        return (int)dp[n][k];
    }
}

code.kotlin:
class Solution {
    fun rearrangeSticks(n:Int,k:Int):Int{
        val dp=Array(n+1){
            LongArray(k+1)
        };
        dp[0][0]=1;
        for(length in 1..n)for(visible in 1..minOf(length,k))dp[length][visible]=(dp[length-1][visible-1]+(length-1).toLong()*dp[length-1][visible])%1_000_000_007;
        return dp[n][k].toInt()
    }
}

code.cpp:
class Solution {
    public: int rearrangeSticks(int n,int k){
        const long long MOD=1000000007;
        vector<vector<long long>> dp(n+1,vector<long long>(k+1));
        dp[0][0]=1;
        for(int length=1;length<=n;++length)for(int visible=1;visible<=min(length,k);++visible)dp[length][visible]=(dp[length-1][visible-1]+(length-1)*dp[length-1][visible])%MOD;
        return dp[n][k];
    }
};
